this["app"]["templates"]["location_gps"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape, __j = Array.prototype.join;function print() { __p += __j.call(arguments, '') }with (obj) { switch (state) {     case ('finished'): ;__p += '\n        <div class="success-message">\n            <p>Success!</p>\n            <p>Accuracy: ' +__e( obj.accuracy ) +' meters</p>\n        </div>\n    '; break;       case ('running'): ;__p += '\n        <div class="info-message">\n            <p>We are trying to get your location. This might take a\n                few minutes...</p>\n            '; if (obj.accuracy) { ;__p += '\n                <p>Accuracy: ' +__e( obj.accuracy ) +' meters\n                    (need less than ' +__e( app.CONF.GPS_ACCURACY_LIMIT ) +'m)</p>\n            '; } ;__p += '\n        </div>\n    '; break;    default: ;__p += '\n        <div class="info-message">\n            <p>We will try to determine your location\n                using the inbuilt phone GPS.</p>\n\n            <p> Please make sure you have turned the phone\'s\n                geolocation on and are well away from large objects.<br/> e.g. <i>trees,\n                    buildings </i></p>\n        </div>\n'; };__p += '\n';}return __p};

this["app"]["templates"]["p_about-org"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape, __j = Array.prototype.join;function print() { __p += __j.call(arguments, '') }with (obj) {__p += '<div data-role="header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-carat-l ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-notext">Back</a>\n    </div>\n    <h1 id=\'about_heading\'>About App</h1>\n</div>\n\n<div data-role="content">\n    <ul data-role="listview">\n        <li>\n            <p>Dragonfly records are vital in order to accurately determine their distribution\n                and numbers, and to advise on conservation for those species that need it. </p>\n\n            <p>Anyone can contribute to the dragonfly dataset and thereby enhance\n                our knowledge of dragonflies. The basic information needed to\n                make a record must answer four simple questions: What species?\n                Where was it seen? When was it seen? Who saw it?</p>\n            <p>\n                Extra value can be added to a record if you count or estimate\n                the numbers present. Even more valuable is evidence of breeding,\n                so please submit records of mating pairs, egg-laying (ovipositing),\n                larvae (nymphs), exuviae (larval skins) and newly-emerged\n                dragonflies (emergents).\n            </p>\n\n            <p>Any records you submit using the <i>iRecord Dragonfly</i> app will be reviewed and\n                verified by an expert before being added to the iRecord <a href="http://www.brc.ac.uk/irecord">website</a>\n                and also shared at 1km resolution via the NBN Gateway in the Dragonfly Recording Network dataset.</p>\n\n            <p>How the <a href="http://www.british-dragonflies.org.uk/">BDS</a> uses records is explained in the DragonflyWatch strategy.</p>\n\n            <p>Thank you for taking part!</p>\n        </li>\n        <li style="padding-top:0; padding-bottom:0">\n            <div data-role="collapsible" class="no-top-border no-top-margin"\n                 data-inset="false" data-iconpos="right" data-collapsed-icon="carat-d" data-expanded-icon="carat-u">\n                <h3>How to make a new record</h3>\n                <p>Please press a <b>plus</b> button next to a species listing on the\n                    <a href="#list">home</a> page and fill in the details of the sighting,\n                    like <b>location</b>, <b>date</b>, <b>number seen</b> etc.</p>\n\n                <p>When finished, press a black <b>Save</b> button (top-right).</p>\n            </div>\n            <div data-role="collapsible" class="no-top-border no-top-margin"\n                 data-inset="false" data-iconpos="right" data-collapsed-icon="carat-d" data-expanded-icon="carat-u">\n                <h3>How to make a multi record</h3>\n                <p>Press the <b>double plus</b> button at the top-right of the <a href="#list">home</a> page\n                    and add your <b>location</b> and <b>date</b>. When done, press the <b>Next</b>\n                    button (top-right) and make a list of the species seen by pressing the <b>plus</b>\n                    button and selecting species from the list. By default, each species shows <i>Ad: Present</i>\n                    To change the number of adults or other life stages, press on the saved species listing (below plus button)\n                    and fill in the details for each life stage observed.</p>\n\n                <p>When finished, press the black <b>Save</b> button (top-right). You will be then asked\n                whether you have recorded all the species seen during your visit.</p>\n            </div>\n            <div data-role="collapsible" data-inset="false" data-iconpos="right" data-collapsed-icon="carat-d" data-expanded-icon="carat-u">\n                <h3>How to sign in/out or register</h3>\n                <p>Go to the <a href="#settings">user settings</a> page\n                    (top-right of <a href="#user">user</a> page) and follow the instructions.</p>\n            </div>\n            <div data-role="collapsible"\n                 data-inset="false" data-iconpos="right" data-collapsed-icon="carat-d" data-expanded-icon="carat-u">\n                <h3>Synchronisation with iRecord</h3>\n                <p>Your saved records will be shown on the <a href="#user">user</a> page.\n                    If the record has reached the database the\n                    <em style="color:red">red</em> cloud icon (saved locally) will become\n                    <em style="color:green">green</em> (synced to the database).</p>\n\n                <p>If you have signed in to your iRecord account and there is a network connection,\n                    the records will be automatically synchronised to the database\n                    in the background. </p>\n                <p>If you have switched the auto synchronisation off on the\n                    <a href="#settings">user settings</a> page or not signed in to iRecord,\n                    then by pressing a saved record with a <em style="color:red">red</em> cloud icon\n                    and filling in your contact details will submit the record to the database.</p>\n            </div>\n            '; if (app.browser.isMobile() && !app.browser.isIOS()) { ;__p += '\n                <div data-role="collapsible" data-inset="false" data-iconpos="right" data-collapsed-icon="carat-d" data-expanded-icon="carat-u">\n                    <h3>How to download the app</h3>\n                    <p>This mobile application is web based, i.e. - it is a\n                        website made for mobile devices. This means that it is hosted\n                        on the BDS server and not Google Play Store or similar place. To save this\n                        website as an app, you need to bookmark it to your home screen, as follows.</p>\n\n                    <p>1. Navigate to <a href="#list">home page</a></p>\n                    <p>2. Find and open your <strong>Browser Menu</strong></p>\n                    <p>3. Tap thw <strong>Add to Home Screen</strong> option</p>\n                </div>\n            '; } ;__p += '\n        </li>\n        <li>\n            <strong>The British Dragonfly Society</strong>\n            <p>The <a href="http://www.british-dragonflies.org.uk/">BDS</a> is supporting a network of dragonfly professionals and volunteers,\n                experts and enthusiasts, all working to survey, monitor,\n                research and conserve dragonflies, learn more about\n                them and secure their future in Britain.</p>\n        </li>\n        <li>\n            <strong>Further information</strong>\n            <p>For further information about the <i>iRecord Dragonfly</i> app and\n                dragonfly recording, please visit the British Dragonfly Society\n                <a href="http://www.british-dragonflies.org.uk/">website</a>.</p>\n        </li>\n    </ul>\n    <ul data-role="listview" class="space-top">\n        <li>\n            <strong>App Development</strong>\n            <p>This app was developed by the BRC mobile development team. For suggestions and feedback\n                please do not hesitate to <a href=\'mailto:apps%40ceh.ac.uk?subject=iRecord%20Dragonflies%20Support%26Feedback&body=%0A%0A%0AVersion%3A%20' +__e( app.VERSION ) +'%0ABrowser%3A ' +__e( window.navigator.appVersion ) +'%0A\'>contact us</a>.</p>\n\n            <p>\n                This app was part-funded via the Centre for Ecology & Hydrology/Joint Nature Conservation Committee partnership supporting BRC.\n                <img src="images/sponsor_logo.png" style="display: block;width: 88%;max-width: 400px;margin: 0 auto"/>\n            </p>\n        </li>\n        <li>\n            <p class="app-version">v' +__e( app.VERSION ) +'</p>\n        </li>\n    </ul>\n</div>';}return __p};

this["app"]["templates"]["p_about"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape;with (obj) {__p += '<div data-role="header" class="rf-header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-carat-l ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-notext">Back</a>\n    </div>\n    <h1 id=\'about_heading\'>About the App</h1>\n</div>\n\n<div data-role="content" class="rf rf-about">\n    <div class="rf-section" style="margin-top:16px;">\n        <div class="rf-section-title">Introduction</div>\n        <p class="rf-body-text">This app features 138 species of dragonflies and damselflies recorded in Singapore. It is designed to provide a quick and convenient reference for identifying and learning about Singapore’s Odonata, with information readily available at your fingertips.</p>\n        <p class="rf-body-text">For more detailed information, we recommend referring to authoritative reference books, such as:</p>\n        <ul class="rf-booklist">\n            <li>A Photographic Guide to the Dragonflies of Singapore &mdash; Tang Hung Bun, Wang Luan Keng &amp; Matti Hämäläinen</li>\n            <li>Dragonflies of Peninsular Malaysia and Singapore &mdash; A. G. Orr</li>\n        </ul>\n    </div>\n\n    <div class="rf-section">\n        <div class="rf-section-title">Dragonflies of Singapore Facebook Group</div>\n        <p class="rf-body-text">The <a target="_blank" href="https://www.facebook.com/groups/295432323905656/" class="rf-link-btn">Dragonflies of Singapore Facebook Group</a> is a community of dragonfly professionals, experts and enthusiasts who come together to observe, document, discuss and research dragonflies and damselflies in Singapore.</p>\n    </div>\n\n    <div class="rf-section">\n        <div class="rf-section-title">App Development</div>\n        <p class="rf-body-text">This app is based on a framework originally developed by the Biological Records Centre (BRC) mobile development team and subsequently modified by Soon Chye.</p>\n    </div>\n</div>';}return __p};

this["app"]["templates"]["p_brc-approved"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape;with (obj) {__p += '<div data-role="header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-carat-l ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-notext">Back</a>\n    </div>\n    <h1 id=\'credits_heading\'>BRC Approved</h1>\n</div>\n\n<div data-role="content">\n    <img src="images/BRC_approved_logo.png" class="brc-approved-logo"/>\n\n    <ul data-role="listview">\n        <li>\n            <p>Wherever you see this logo on a biological recording app you can be assured that the\n                data you submit will be: made available to experts for quality assurance;\n                made available for conservation and research and preserved for long-term use.</p>\n        </li>\n        <li>\n            <p>This logo indicates that your data is:</p>\n\n            <ul class="list-normal-white-space">\n                <li><p>Sent to the Biological Record Centre’s data warehouse linked to the iRecord\n                        system where it is accessible to you as the recorder, to an expert community\n                        of verifiers and other users of iRecord.</p>\n                </li>\n                <li>\n                    <p>Quality assured data is passed onto Local Environmental Records Centres,\n                        National Recording Schemes and to the NBN Gateway.</p>\n                </li>\n            </ul>\n        </li>\n        <li>\n            <p><strong>About BRC</strong></p>\n            <p>\n                The <a href="http://www.brc.ac.uk" rel="external">Biological Records Centre</a> (BRC), established in 1964, is a national\n                focus in the UK for terrestrial and freshwater species recording.\n                BRC works closely with the voluntary recording community, principally\n                through support of national recording schemes and societies. BRC is\n                supported by the Joint Nature Conservation Committee (JNCC) and the\n                Centre for Ecology & Hydrology (CEH) within the Natural Environment\n                Research Council (NERC). The work of BRC is a major component of the\n                National Biodiversity Network (NBN).</p>\n        </li>\n        <li>\n            <p><strong>Which app should I use?</strong></p>\n\n            <p>You might have noticed that several of\n                <a href="http://www.brc.ac.uk/apps" rel="external">BRC apps</a>\n                feature some of the same species?  We have introduced the BRC Approved\n                logo to signify that data from our apps all go to the same place.\n                Therefore, you are free to choose which app you use to record a given species.\n                All records will be sent to the same place, treated in the same way and will meet\n                the established standards required by the Biological  Record Centre.</p>\n        </li>\n\n    </ul>\n</div>';}return __p};

this["app"]["templates"]["p_comment"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape;with (obj) {__p += '<div data-role="header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-delete ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-left">Cancel</a>\n    </div>\n    <h1>Comment</h1>\n    <div class=\'ui-btn-right\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <button id="comment-save" class="ui-btn ui-icon-plus ui-alt-icon\n        ui-nodisc-icon ui-btn-icon-right">Save</button>\n    </div>\n</div>\n<div data-role="content">\n    <div class="info-message">\n        <p>Please add any extra info about this record.</p>\n    </div>\n    <textarea id="record-comment" cols="80" rows="4" placeholder="Add a note"></textarea>\n</div>\n';}return __p};

