this["app"]["templates"]["p_privacy"] = function(obj) {obj || (obj = {});var __t, __p = '', __e = _.escape;with (obj) {__p += '<div data-role="header" data-position="fixed" data-tap-toggle="false">\n    <div class=\'ui-btn-left\' data-role=\'controlgroup\' data-type=\'horizontal\'>\n        <a href=\'#\' data-rel=\'back\' class="ui-btn ui-icon-carat-l ui-nodisc-icon\n        ui-alt-icon ui-btn-icon-notext">Back</a>\n    </div>\n    <h1 id=\'privacy_heading\'>Privacy Policy</h1>\n</div>\n\n<div data-role="content">\n    <ul data-role="listview">\n        <li>\n            <p>Thank you for your interest in this Dragonfly Recording Scheme\n                and for your help in providing data on these species. This page explains\n                how any personal data you submit to the <i>iRecord Dragonflies</i> app will be stored and used.</p>\n        </li>\n        <li>\n            <strong>Use of your name</strong>\n\n            <p>If you choose to create a user account for the app, this will be created on the Biological\n                Record Centre\'s iRecord system: <a href="http://www.brc.ac.uk/irecord" rel="external">http://www.brc.ac.uk/irecord</a>.\n                This enables you to log in and see your records and those submitted by other people for all\n                species. Your name, as specified when you create the account, will appear next to your\n                records and will be viewable by other users of iRecord.</p>\n        </li>\n        <li>\n            <strong>E-mail address</strong>\n\n            <p>To create an account you will need to supply your e-mail address, which will be used in order\n                to validate your account and to send you periodic updates and important information about the\n                project. Your email address will not be shown and disseminated with your records but will be\n                available to the verifying experts if they need to contact you about your sightings. You are\n                able to delete your iRecord account or opt out of receiving emails at any time.</p>\n        </li>\n        <li>\n            <strong>Other information collected by the application</strong>\n\n            <p>All records submitted will be stored permanently on a secure server at the Biological Record\n                Centre. Records will be made accessible to Local Environmental Record Centres, conservation\n                organisations, scientific researchers, the NBN Gateway and the public.</p>\n        </li>\n        <li>\n            <strong>How long will my data be stored?</strong>\n\n            <p>Your submitted records will be stored permanently and used to inform the conservation and study\n                of dragonflies and related insects in the future.</p>\n        </li>\n        <li>\n            <strong>Who will have access to my personal data?</strong>\n\n            <p>Only those directly involved in developing this app and running this Dragonfly Recording Scheme\n                or verifying records as experts, will have access to your email address.\n                Unless required by law, data will not be made available to any third parties unless we have\n                obtained your permission to do so.</p>\n        </li>\n        <li>\n            <strong>Use of images submitted with the app</strong>\n\n            <p>By submitting a photograph with this app you:</p>\n            <ul class="list-normal-white-space">\n                <li>\n                    <p>Give the project and its partners permission to publish the file/s on their respective websites\n                        and to use the file/s in any publicity materials they produce.</p>\n                </li>\n                <li>\n                    <p>Grant the project and its partners a non-exclusive, worldwide licence to republish the file/s\n                        in any format including, without limitation, in print and electronic formats.</p>\n                </li>\n                <li>\n                    <p>Warrant that the file is entirely your own work and has not been copied in whole, or in part,\n                        from any 3rd party and does not infringe any 3rd party intellectual property rights.</p>\n                </li>\n                <li>\n                    <p>Waive all moral rights in, and arising from your photograph(s), but retain\n                        ownership of the copyright in your file(s) as its author.</p>\n                </li>\n            </ul>\n        </li>\n        <li>\n            <p>Wherever possible you will receive credit for the reproduction of your work on, or next to, your\n                photograph or file, although we reserve the right to exclude a direct attribution where this\n                affects the aesthetic of the reproduction.</p>\n        </li>\n\n</div>';}return __p};

